def match(orders):
    trades = []
    buy_book = []  # list of (price, arrival_time, id, qty) - sorted by (-price, arrival_time)
    sell_book = []  # list of (price, arrival_time, id, qty) - sorted by (price, arrival_time)
    order_map = {}  # id -> (side, price, arrival_time) for tracking resting orders
    arrival_time = 0
    cancelled = set()

    def add_to_buy_book(price, id, qty):
        buy_book.append((price, arrival_time, id, qty))
        buy_book.sort(key=lambda x: (-x[0], x[1]))
        order_map[id] = ('buy', price, arrival_time)

    def add_to_sell_book(price, id, qty):
        sell_book.append((price, arrival_time, id, qty))
        sell_book.sort(key=lambda x: (x[0], x[1]))
        order_map[id] = ('sell', price, arrival_time)

    def match_buy(id, price, qty, is_market=False):
        nonlocal arrival_time
        remaining = qty

        while remaining > 0 and sell_book:
            sell_price, sell_arrival, sell_id, sell_qty = sell_book[0]

            # For market orders, match any price. For limit orders, only match at or below price
            if not is_market and sell_price > price:
                break

            trade_qty = min(remaining, sell_qty)
            trades.append([id, sell_id, sell_price, trade_qty])

            remaining -= trade_qty
            sell_book[0] = (sell_price, sell_arrival, sell_id, sell_qty - trade_qty)

            if sell_book[0][3] == 0:
                sell_book.pop(0)
                if sell_id in order_map:
                    del order_map[sell_id]

        # If there's remaining qty and it's a limit order (not ioc/market), add to book
        return remaining

    def match_sell(id, price, qty, is_market=False):
        nonlocal arrival_time
        remaining = qty

        while remaining > 0 and buy_book:
            buy_price, buy_arrival, buy_id, buy_qty = buy_book[0]

            # For market orders, match any price. For limit orders, only match at or above price
            if not is_market and buy_price < price:
                break

            trade_qty = min(remaining, buy_qty)
            trades.append([buy_id, id, buy_price, trade_qty])

            remaining -= trade_qty
            buy_book[0] = (buy_price, buy_arrival, buy_id, buy_qty - trade_qty)

            if buy_book[0][3] == 0:
                buy_book.pop(0)
                if buy_id in order_map:
                    del order_map[buy_id]

        return remaining

    for order in orders:
        arrival_time += 1

        if order[0] == 'limit':
            _, id, side, price, qty = order

            if side == 'buy':
                remaining = match_buy(id, price, qty, is_market=False)
                if remaining > 0:
                    add_to_buy_book(price, id, remaining)
            else:  # sell
                remaining = match_sell(id, price, qty, is_market=False)
                if remaining > 0:
                    add_to_sell_book(price, id, remaining)

        elif order[0] == 'ioc':
            _, id, side, price, qty = order

            if side == 'buy':
                match_buy(id, price, qty, is_market=False)
            else:  # sell
                match_sell(id, price, qty, is_market=False)

        elif order[0] == 'market':
            _, id, side, qty = order

            if side == 'buy':
                match_buy(id, float('inf'), qty, is_market=True)
            else:  # sell
                match_sell(id, 0, qty, is_market=True)

        elif order[0] == 'cancel':
            _, id = order

            if id in order_map:
                side, price, arr_time = order_map[id]

                if side == 'buy':
                    buy_book[:] = [(p, a, oid, q) for p, a, oid, q in buy_book if oid != id]
                else:
                    sell_book[:] = [(p, a, oid, q) for p, a, oid, q in sell_book if oid != id]

                del order_map[id]

    return trades

